#!/usr/bin/env bash
# Read real values back from every table / collection / index.
ch() { docker exec openetl-lab-clickhouse clickhouse-client --user lab --password lab -q "$1"; }
pg() { docker exec openetl-lab-postgres psql -U lab -d openetl -At -F ' | ' -c "$1"; }
echo "== PostgreSQL"; for t in $(pg "select tablename from pg_tables where schemaname='public'"); do echo "$t: $(pg "select count(*) from $t") rows; e.g. $(pg "select left(replace(text,E'\n',' '),90) from $t offset 3 limit 1")"; done
echo "== ClickHouse"; for t in $(ch "SELECT name FROM system.tables WHERE database='openetl'"); do echo "$t: $(ch "select count() from openetl.$t") rows; e.g. $(ch "select substring(replaceAll(text,'\n',' '),1,90) from openetl.$t limit 1 offset 1")"; done
echo "== MongoDB"; docker exec openetl-lab-mongodb mongosh --quiet openetl --eval 'db.getCollectionNames().sort().forEach(c=>print(c+": "+db[c].countDocuments()+" docs; e.g. "+(db[c].findOne({}, {text:1,_id:0})||{text:""}).text.replace(/\n/g," ").slice(0,90)))'
echo "== Elasticsearch"; for i in $(curl -s 'http://127.0.0.1:9200/_cat/indices?h=index' | grep -v '^\.' | sort); do echo "$i: $(curl -s http://127.0.0.1:9200/$i/_count | python3 -c 'import sys,json;print(json.load(sys.stdin)["count"])') docs; e.g. $(curl -s "http://127.0.0.1:9200/$i/_search?size=1&from=2" | python3 -c 'import sys,json;h=json.load(sys.stdin)["hits"]["hits"];print(h[0]["_source"].get("text","").replace("\n"," ")[:90] if h else "")')"; done
echo "== Qdrant"; for c in $(curl -s http://127.0.0.1:6333/collections | python3 -c 'import sys,json;print(*[c["name"] for c in json.load(sys.stdin)["result"]["collections"]])'); do echo "$c: $(curl -s http://127.0.0.1:6333/collections/$c | python3 -c 'import sys,json;print(json.load(sys.stdin)["result"]["points_count"])') points; e.g. $(curl -s -X POST http://127.0.0.1:6333/collections/$c/points/scroll -H 'content-type: application/json' -d '{"limit":1,"with_payload":true}' | python3 -c 'import sys,json;p=json.load(sys.stdin)["result"]["points"];print(p[0]["payload"].get("content","").replace("\n"," ")[:90])')"; done
